int main() {
    long long  sum, bucketBallNums;
    cin >> sum >> bucketBallNums;
    vector<long long> ans(bucketBallNums);
    // 输入桶中数量求和值
    long long  totalSum = 0;
    long long  maxBall = 0;
    for (int i = 0; i < bucketBallNums; i++) {
        cin >> ans[i];
        totalSum += ans[i];
        maxBall = max(maxBall, ans[i]);
    }

    if (totalSum <= sum) {
        cout << "[]";
        return 0;
    }
    // 二分 求出最大容量值
    int left = 0, right = maxBall;
    while (left < right) {
        int mid = (left + right + 1) >> 1;
        if (check(ans, mid, sum)) {
            left = mid;
        } else {
            right = mid - 1;
        }

    }
    // 按要求进行输出
    cout << "[";
    for (int i = 0; i < ans.size(); i++) {
        if (i != 0) {
            cout << ",";
        }
        cout << max(0ll, ans[i] - left);
    }
    cout << "]";
    return 0;
​
}

