import java.util.*;
​
public class Main {
    static boolean check(List<Long> ans, long maxCap, long sum) {
        long res = 0;
        for (long ball : ans) {
            res += (ball > maxCap) ? maxCap : ball; // 避免调用 Math.min
            if (res > sum) return false; // 立即返回，减少不必要的计算
        }
        return res <= sum;
    }
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long sum = scanner.nextLong();
        int bucketBallNums = scanner.nextInt();
        List<Long> ans = new ArrayList<>();

        long totalSum = 0, maxBall = 0;
        for (int i = 0; i < bucketBallNums; i++) {
            long num = scanner.nextLong();
            ans.add(num);
            totalSum += num;
            maxBall = Math.max(maxBall, num);
        }
        scanner.close();

        if (totalSum <= sum) {
            System.out.println("[]");
            return;
        }
​
        // 二分查找最大容量值
        long left = 0, right = maxBall;
        while (left < right) {
            long mid = left + (right - left + 1) / 2; // 避免 (left + right) 溢出
            if (check(ans, mid, sum)) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }
​
        // 按格式输出结果
        StringBuilder sb = new StringBuilder();
        sb.append("[");
        for (int i = 0; i < ans.size(); i++) {
            if (i > 0) sb.append(",");
            sb.append(Math.max(0, ans.get(i) - left));
        }
        sb.append("]");
        System.out.println(sb.toString());
    }
}
