package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 检查是否可以满足 sum 约束
func check(ans []int, maxCap, sum int) bool {
    res := 0
    for _, val := range ans {
        if val < maxCap {
            res += val
        } else {
            res += maxCap
        }
    }
    return res <= sum
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取第一行
    line, _ := reader.ReadString('\n')
    parts := strings.Fields(line)
    sum, _ := strconv.Atoi(parts[0])
    bucketBallNums, _ := strconv.Atoi(parts[1])
​
    // 读取第二行
    line, _ = reader.ReadString('\n')
    numParts := strings.Fields(line)
​
    ans := make([]int, bucketBallNums)
    totalSum, maxBall := 0, 0
​
    for i := 0; i < bucketBallNums; i++ {
        num, _ := strconv.Atoi(numParts[i])
        ans[i] = num
        totalSum += num
        if num > maxBall {
            maxBall = num
        }
    }
​
    if totalSum <= sum {
        fmt.Println("[]")
        return
    }
​
    // 二分查找最大容量值
    left, right := 0, maxBall
    for left < right {
        mid := (left + right + 1) / 2
        if check(ans, mid, sum) {
            left = mid
        } else {
            right = mid - 1
        }
    }
​
    // 按格式输出结果
    fmt.Print("[")
    for i, val := range ans {
        if i > 0 {
            fmt.Print(",")
        }
        fmt.Print(max(0, val-left))
    }
    fmt.Println("]")
}
​
func max(a, b int) int {
    if a > b {
        return a
    }
    return b
}
